import * as THREE from 'three/webgpu';
import { texture as tslTexture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load ceramic grain texture
  const textureUrl = '/prism-assets/chrome/ceramic-grain.map.png';
  const map = ctx.textureLoader.load(textureUrl);
  map.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry matching 512:320 atlas aspect ratio
  const planeWidth = 0.8;
  const planeHeight = planeWidth / (512 / 320);
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // TSL-based material with texture node
  const colorNode = tslTexture(map, uv());
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: colorNode,
  });

  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // Render text content using fontAtlas
  const textContent = config.textContent || 'Features 3';
  const textObject = ctx.fontAtlas.render(textContent, {
    font: 'Lora',
    size: 0.34, // headline type scale
    weight: 400,
    color: '#16161d', // ink color for contrast
  });

  if (textObject) {
    textObject.position.z = 0.01; // slight z-offset in front of plane
    group.add(textObject);
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    map.dispose();
  };

  group.userData.handlers = {};

  return group;
}
